#include <vector>
#include <list>
#include <iostream>

int main() {
    std::list<double> source = {1.1, 2.2, 3.3};

    // Uses InputIterator range constructor
    // double is convertible to int
    std::vector<int> target(source.begin(), source.end()); 

    // O(N) complexity for initialization

    std::cout << target[0] << std::endl; // Output: 1

    // Example of using non-container range (C-array)
    int arr[] = {10, 20, 30};
    std::vector<int> v_arr(std::begin(arr), std::end(arr));
}
